38	// SandwichRule configures the sandwich rule: whether it runs and the
39	// severity of its conclusions.
40	type SandwichRule struct {
41		Enabled  bool `json:"enabled"`
42		Severity int  `json:"severity"`
43	}
44	
45	// DisplacementRule configures the displacement rule. A victim is flagged
46	// only when the previous swap's GasPrice strictly exceeds Multiplier times
47	// the victim's.
48	type DisplacementRule struct {
49		Enabled    bool `json:"enabled"`
50		Severity   int  `json:"severity"`
51		Multiplier int  `json:"multiplier"`
52	}
53	
54	// RuleSet is the complete declaration of both detection rules. Every
55	// version must declare both rules in full.
56	type RuleSet struct {
57		Sandwich     SandwichRule     `json:"sandwich"`
58		Displacement DisplacementRule `json:"displacement"`
59	}
60	
61	// RuleVersion is a named, immutable set of rule parameters.
62	type RuleVersion struct {
63		ID    string  `json:"id"`
64		Rules RuleSet `json:"rules"`
65	}
