132	func mustRuleVersion(t *testing.T, spec string) RuleVersion {
133		t.Helper()
134		v, err := ParseRuleVersion([]byte(spec))
135		if err != nil {
136			t.Fatalf("ParseRuleVersion: %v", err)
137		}
138		return v
