362		// archA's multiplier 3 nor candC's multiplier 2.
363		emptyDir := t.TempDir()
364		register(t, emptyDir, archivedVersionSpec)
365		register(t, emptyDir, candidateVersionSpec)
366		emptyInput := cmpBlockLine("1", "0empty", 1,
367			cmpSwap("0g0", "p", "w", 15, 0),
368			cmpSwap("0g1", "p", "u", 10, 1),
369		)
370		if _, err := ReplayWithVersion(strings.NewReader(emptyInput), emptyDir, "archA"); err != nil {
371			t.Fatal(err)
372		}
373		empty, err := Compare(emptyDir, "1", "0empty", "candC")
374		if err != nil {
375			t.Fatal(err)
376		}
377		for name, fs := range map[string][]ReportFinding{
378			"originalFindings": empty.OriginalFindings,
379			"comparedFindings": empty.ComparedFindings,
380			"added":            empty.Added,
381			"removed":          empty.Removed,
382		} {
383			if fs == nil || len(fs) != 0 {
384				t.Fatalf("%s must be a non-nil empty slice, got %v", name, fs)
385			}
386		}
387		if empty.Changed == nil || len(empty.Changed) != 0 {
388			t.Fatalf("changed must be a non-nil empty slice, got %v", empty.Changed)
389		}
390		if len(empty.Swaps) != 2 {
391			t.Fatalf("empty-findings block must still carry its swap records: %+v", empty.Swaps)
392		}
393		// JSON must show [], never null, for all five lists.
394		raw, err := json.Marshal(empty)
395		if err != nil {
396			t.Fatal(err)
397		}
398		for _, key := range []string{`"originalFindings":[]`, `"comparedFindings":[]`, `"added":[]`, `"removed":[]`, `"changed":[]`} {
399			if !strings.Contains(string(raw), key) {
400				t.Fatalf("JSON missing %s in %s", key, raw)
401			}
402		}
403	}
