465	// corruptStoredVersion rewrites the stored archive document of one
466	// registered version, simulating an archive that is still valid JSON but
467	// whose registered version no longer satisfies the registration rules.
468	func corruptStoredVersion(t *testing.T, dir, id string, mutate func(ver map[string]any)) {
469		t.Helper()
