477			t.Fatal(err)
478		}
479		for _, entry := range doc["versions"].([]any) {
480			ver := entry.(map[string]any)
481			if ver["id"] == id {
482				mutate(ver)
483			}
484		}
485		out, err := json.MarshalIndent(doc, "", "  ")
486		if err != nil {
487			t.Fatal(err)
488		}
489		if err := os.WriteFile(archivePath, out, 0o644); err != nil {
490			t.Fatal(err)
491		}
