	result := parseCompareJSON(t, res.stdout)
	if result.OriginalVersion.ID != "builtin" ||
		result.OriginalVersion.Rules.Sandwich.Severity != 3 ||
		result.OriginalVersion.Rules.Displacement.Multiplier != 2 {
